<?php require 'bootstrap.php';require_login();require 'layout.php';$cart=$_SESSION['cart']??[];if(!$cart)redirect('cart.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{check_csrf();$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$addr=trim($_POST['address']??'');$method=$_POST['method']??'';if(!$name||!$phone||strlen($addr)<10||!in_array($method,['cod','bank_transfer'],true))throw new RuntimeException('Complete all checkout fields');$pdo=db();$pdo->beginTransaction();$total=0;$lines=[];foreach($cart as $id=>$qty){$qty=(int)$qty;if($qty<1)throw new RuntimeException('Invalid quantity');$s=$pdo->prepare('SELECT id,name,price,stock FROM products WHERE id=? AND is_active=1 FOR UPDATE');$s->execute([(int)$id]);$p=$s->fetch();if(!$p||$p['stock']<$qty)throw new RuntimeException('A product is unavailable or out of stock');$total+=(float)$p['price']*$qty;$lines[]=[$p,$qty];}$s=$pdo->prepare('INSERT INTO orders(user_id,shipping_name,shipping_phone,shipping_address,total) VALUES(?,?,?,?,?)');$s->execute([current_user()['id'],$name,$phone,$addr,$total]);$order=$pdo->lastInsertId();foreach($lines as [$p,$qty]){$s=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,quantity,unit_price) VALUES(?,?,?,?,?)');$s->execute([$order,$p['id'],$p['name'],$qty,$p['price']]);$s=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');$s->execute([$qty,$p['id']]);}$s=$pdo->prepare('INSERT INTO payments(order_id,method,status) VALUES(?,?,?)');$s->execute([$order,$method,$method==='cod'?'unpaid':'pending_verification']);$pdo->commit();$_SESSION['cart']=[];redirect('orders.php?placed='.$order);}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}head_html('Checkout');?><h1>Checkout</h1><p class="muted">Demo checkout: Cash on delivery or manual bank transfer. No online payment gateway is connected.</p><?php if($error):?><p class="alert"><?=e($error)?></p><?php endif;?><form method="post" class="panel stack wide"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Full name<input name="name" value="<?=e(current_user()['name'])?>" required></label><label>Phone<input name="phone" required></label><label>Full shipping address<textarea name="address" rows="4" required minlength="10"></textarea></label><label>Payment method<select name="method"><option value="cod">Cash on delivery</option><option value="bank_transfer">Manual bank transfer (pending verification)</option></select></label><button class="btn">Place order</button></form><?php foot_html();